   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The blade sank deeper, drawing blood from her neck.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="How did she die?", msg_color="", msg_size=0, talker="Dawn", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4104", 0, 0, -17, 213}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="No one knows. The Starcall Abbey wanted to revive her corpse. I was just the executor.", msg_color="", msg_size=0, talker="Rosana", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4104", 0, 0, -17, 213}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Why would Starcall Abbey need her body?", msg_color="", msg_size=0, talker="Dawn", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4104", 0, 0, -17, 213}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Rosana shook her head, the growing pain making her lips tremble.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Then why are you still alive? Has that Knight Commander lost her mind?", msg_color="", msg_size=0, talker="Dawn", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4104", 0, 0, -17, 213}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The Starcall Abbey fed me classified intel—secrets I used to earn the Stellar Knights' trust, climbing higher until I became a Rose they couldn't remove.", msg_color="", msg_size=0, talker="Rosana", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [43]={next_id=44, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="That intel... included Vilatria's buried history and hidden truths. This underground prison was one of them.", msg_color="", msg_size=0, talker="Rosana", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [44]={next_id=45, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Later... the Starcall Abbey tried to erase me. The Stellar Knights wouldn't take me back. So I fled Stardom and hid.", msg_color="", msg_size=0, talker="Rosana", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [45]={next_id=46, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I'm alive because I still have value. For your arrival, Lady Tiya spared me. She ordered me to live in regret and suffering, to atone for my sins.", msg_color="", msg_size=0, talker="Rosana", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [46]={next_id=47, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="So please... don't kill me.", msg_color="", msg_size=0, talker="Rosana", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [47]={next_id=48, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="For the first time, Rosana showed emotion—like a stray dog wagging its tail at a passerby, begging for mercy.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [48]={next_id=49, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="As Dawn stayed silent, Rosana shut her eyes, bracing for death.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [49]={next_id=50, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="But it never came. The pain vanished, the spear withdrawing from her throat.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [50]={next_id=51, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Rosana gasped for air, nearly collapsing. The lantern in her hand swayed violently, casting jagged shadows between them.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [51]={next_id=52, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="She had wondered if Dawn would kill her upon learning the truth. Yet Dawn restrained that urge, letting her cling to this wretched existence.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
